mapper.delete:
DELETE FROM tb_eval_item
WHERE review_master_code = #{reviewMasterCode}
  AND company_code = #{companyCode}

mapper.select:
SELECT COUNT(*) AS total_member_cnt
FROM tb_user_master u
WHERE u.company_code = #{companyCode}
  AND u.dept = (
            SELECT dept
            FROM tb_user_master
            WHERE company_code = #{companyCode}
            AND user_id = #{userId}
  )
  AND u.user_id  <>  #{userId}
  AND u.user_status = 0
